def solve_nqueens_with_constraints(n, fixed):
    """Solve N-Queens with fixed queen positions using backtracking."""

    # Initialize solution array
    queens = [-1] * n

    # Place fixed queens
    for row, col in fixed.items():
        queens[row] = col

    # Check if fixed queens are consistent with each other
    fixed_rows = list(fixed.keys())
    for i in range(len(fixed_rows)):
        for j in range(i+1, len(fixed_rows)):
            r1, c1 = fixed_rows[i], fixed[fixed_rows[i]]
            r2, c2 = fixed_rows[j], fixed[fixed_rows[j]]
            if c1 == c2:
                print(f"Conflict: rows {r1} and {r2} both in column {c1}")
                return None
            if abs(r1-r2) == abs(c1-c2):
                print(f"Diagonal conflict: rows {r1},{r2} cols {c1},{c2}")
                return None

    def is_safe(row, col):
        for r in range(n):
            if queens[r] == -1:
                continue
            if r == row:
                continue
            c = queens[r]
            if c == col:
                return False
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True

        # Skip fixed rows
        if queens[row] != -1:
            if is_safe(row, queens[row]):
                return backtrack(row + 1)
            else:
                return False

        for col in range(n):
            if is_safe(row, col):
                queens[row] = col
                if backtrack(row + 1):
                    return True
                queens[row] = -1

        return False

    if backtrack(0):
        return queens
    return None

